  "literacy.tutorial.title": "कलाकृतिआव नोंथांखौ बरायबाय — बेयो माबोरै खामानि मावो",
  "literacy.tutorial.subtitle": "आरिमुगिरिफोरनि थाखाय बानायनाय जादों। टेकनिकेल कम्पिउटार रोंग'थि गैयालासे गावनि शिल्पखौ गासै भारतआवनो फान।",
  "literacy.tutorial.step1Title": "1. गावनि बिमा रावाव रायज्लाय",
  "literacy.tutorial.step1Desc": "type (टाइप) खालामनो गोनांथि गैया। नोंथांनि शिल्पखौ फोरमायग्रा मोनसे गुसुं गारां न'टखौ रेकर्ड खालाम। जोंनि AI आ फारिलाइखौ लिरो आरो लिरो।",
  "literacy.tutorial.step2Title": "2. गाव हारसिङै AI स्टुडिय लाइटिंनि",
  "literacy.tutorial.step2Desc": "नोंथांनि मबाइलाव गोरलै फट' ला। जोंनि AI आ मुखुब मावबादानि बेकग्राउण्डखौ साफा खालामो आरो मिथिंगायारि सोरांखौ समानथि खालामो।",
  "literacy.tutorial.step3Title": "3. मोजां बेसेननि बोसोन होनाय",
  "literacy.tutorial.step3Desc": "जों नोंथांनि गोथां मुवा आरो सानफ्रोमबोनि मावदांसानि खरसाखौ सानना लायो जाहाथे नोंथाङा माब्लाबाबो गावनि मोननांगौ खामायनायनि गाहायाव फाननो हाया।",
  "literacy.tutorial.step4Title": "4. थोंजों बेंकनि रां होनायफोर",
  "literacy.tutorial.step4Desc": "बायग्राफोरा DBT नि गेजेरजों थोंजोङै नोंथांनि भेरिफाइड बेंक एकाउन्टाव रां होयो। लाथिख' गेजेरनि मासुल।",
  "literacy.tutorial.close": "मोनबाय, फै जागायनि",
  "literacy.tutorial.open": "बेयो माबोरै खामानि मावो",
