  "pdp.bullet.authentic": "{origin} आव गासैबो नोंथांनि आं दाबनाय गोरोब {craft} शिल्प।",
  "pdp.bullet.gi": "भौगोलिक सूचक गोहो होनाय ({giNo}) — रैखाथियारनाय गं, मेसिन दाबनाय बासनाय नङा।",
  "pdp.bullet.cluster": "लिस्ट खालामनायनि सिगां शिल्प क्लस्टार्नि परम्परिक कौशल जागायथाव खालामबाय।",
  "pdp.bullet.material": "मुल: {material}। रंग आरो बुनथिखौनि थोजासे बेजायखांथाय नोंथांनि आंनि जायखौ फोरमायो, गोरलैनाय नङा।",
  "pdp.bullet.mto": "अर्डार निफ्राय दाबनाय: नोंथांनि अर्डारनि उनाव मुं सिगां लांबाय, बेबाथोंनो थाखाय गैयिथासो लांबाय।",
  "pdp.bullet.ready": "थां स्टक: शिल्पिया 2 मुं सान सिमाव पैक खालाम्नो दैथियारो।",
  "pdp.bullet.direct": "बिजोना गंसे गंसे {artisan} नि बैंक खाताव जायो — गुबुन मानसि जायाब्ला जागाय।",
  "pdp.bullet.sealed": "जागायथाव कौशलखौ लिस्ट खालामनाय, गोमानि-गोयै गंग-हागारि मुहुर सोमोन्दोव दैथियारो।",
