  "pdp.material.default": "गामियारि, थानि मुल",
  "pdp.care.dryClean": "जुनाव सफाइ सो खालाम। मलमलआव मुहुर खालाम्नो गैयिथासो सान गासोखौ जागायथाव।",
  "pdp.care.handWash": "थांदा दैजों गोख्रों सोबोनजों सोमजिरै आं दाबनाय सिजि। हांखर आव गोरां खालाम।",
  "pdp.care.wipe": "सोमजिरै जुनाव बोसोरजों फुसां। जागायथाव थाब; डिशवाशार आव फैसां नाय।",
  "pdp.care.polish": "मोनोब्ला जुनाव बोसोरजों फुसुं। दै आरो एसिद क्लिनार सिथोन।",
  "pdp.care.dry": "हिनजाव निफ्राय सिथोन। सोमजिरै ब्रसजों धुला फुसां।",
  "pdp.care.frame": "काथिनि उनाव फ्रेम खालाम। हिनजाव फार आरो सान गासो निफ्राय सिथोन।",
  "pdp.care.default": "जागायथाव थाब। सोमजिरै जुनाव बोसोरजों सोमजिरै साफा खालाम।",
  "pdp.review.1.title": "फटोखौ बुसुं गोबां साफा",
  "pdp.review.1.body": "{craft} नि मुं गुबुन साफाब्ला गोबां बेसेल। थोजासे बेजायखांथाय आं दाबनायखौ फोरमायो। जोबोद जागायथाव पैक खालामनाय जायो।",
  "pdp.review.2.title": "बुहुमबो टाकाया मोनगोन जायो",
  "pdp.review.2.body": "बिजोना गंसे गंसे {artisan} थाखाय जायो सोमोन्दोव मिथिनायनि उनाव फैसलाया सोलोंथोनाय जाबाय। म्यूजियमनि दाबथाय।",
  "pdp.review.3.title": "गोरब, थोजासे सम गोयै",
  "pdp.review.3.body": "मियागुनि बुसुं थारि सान गोयै फैबाय, नाथाय शिल्पिया दैथियारि मुं गोयैनि सोलोमबो होबाय। बिजिरनाया बुसुं गोरब।",
  "pdp.review.4.title": "मुहुरखौ गिजाम खालामबाय, गासैबो गोरोब",
  "pdp.review.4.body": "मोननायनि उनाव गंग-हागारि गोहोखौ गिजाम खालामबाय आरो लिस्टजों गोरोबबाय मिलिबाय। जोबथाय आन्लाइन शिल्प खरेदीआव जागायथाव मोनबाय।",
  "pdp.review.5.title": "गोरब, नाथाय मुसुखा गिजाम खालाम",
  "pdp.review.5.body": "गोरब शिल्प, नाथाय मियागुनि बुसुं थोजा। अर्डार खालामनायनि सिगां बिबारनि तालिकाआव मुसुखा फर।",
  "pdp.qa.1.q": "बे आं दाबनाय मो एबा मेसिन?",
  "pdp.qa.1.a": "गासैबो आं दाबनाय। जीआइ टेग आरो गंग-हागारि मुहुर गुबैबो कौशलखौ जागायथाव खालामो।",
  "pdp.qa.2.q": "आं गुबुन रंग सोलोंनो हायो मो?",
  "pdp.qa.2.aMto": "हां, अर्डार निफ्राय दाबनाय बिजिरनायाव गैयिथासो लांनो हायो — अर्डार टिप्पणीआव लिख।",
  "pdp.qa.2.aReady": "बे थां स्टकनि बिजिरनाय, बेबाथोंनो रंगफोर फोरमायनायबादि दं। सोलैथार अर्डारनि थाखाय शिल्पिखौ दैथियारि मुं होन।",
  "pdp.qa.3.q": "दैथियारनोबो बेखौ बेंगबो पैक खालामो?",
  "pdp.qa.3.a": "बोसोराव, उनाव बबल रापाव सोरजिथिनो दुबेल दिवालनि बक्साव। गोमानि बिजिरनायनि थाखाय गैयिथासो क्रेट।",
  "pdp.qa.4.q": "सिजिबो उनाव रंगा फिकारगोन मो?",
  "pdp.qa.4.a": "गामियारि रंगफोर बोसोरनि उनाव थोजासे सोमजिरै जाया, बे स्वाभाविक। रंगखौ जागायथाव थाखाय जागायथाव सोलोमबोफोर लाबो।",
  "pdp.storefront.bio": "{name} या {district} आव {craft} शिल्प खालामो आरो खरेदारमोनखौ गंसे गंसे फेसाना।",
