  "pdp.trivia.heading": "नोंथाङ मोनदों मा?",
  "craft.weaving.funFact": "बनारसी ब्रोकेड ताँत जायगिरिफोरा जरी काम जाय रेशम शाड़ी मोनगोन थाखाय गंसे दान समय लागिबाय दं।",
  "craft.block-printing.funFact": "अजरख ब्लक-प्रिन्ट रोखा गोबां रं मोनगोन थाखाय १६ फेस रं, सिगां आरो सुखानाय गादांबाय दं।",
  "craft.pottery.funFact": "निजामाबादनि गाबखौ मात्तोम गोबां जोबथानाय गाब रं ओखा गोबां धुवां आव पोरगोन जायो, रं आबो ग्लेजनिफ्राय नङा।",
  "craft.metalwork.funFact": "बिदरी शिल्पनि सिबार खामानि जोबथानाय बिदर फर्तनि सिफुंआव मोनगोन मुं मित्थि रोखोमनि मात्ति जायो।",
  "craft.woodwork.funFact": "चन्नपटनानि बांथि खेलमा फोरा दानसुबुं १०० सम गोबां बोसोरनि आग्लाइ रोखोमाव सानायो।",
  "craft.embroidery.funFact": "लक्नौनि चिकनकारी गुदि आव सुजि जायनाय गोबां रोखोमनि सुजिखांथि थायो।",
  "craft.painting.funFact": "मधुबनी सिख्ला बिहारनि हिनजाव फोरा दं नोगोरनि मात्ति देवाल आव सिख्ल दंख्रांबाय आरोंबाय।",
  "craft.basketry.funFact": "मुंज दैला डोखोर सानायाव गोरैनि दैनि जायगा नि दैलाखौ जायखांथि गथ्रा बादि खोरांथिनाव सानायो।",
  "craft.jewellery.funFact": "कटकनि सिबार तारकशी खोपोर निख्रुइ आबो गिबि सिबार गुथाराव सानायो।",
  "craft.leather.funFact": "कोल्हापुरी चप्पल गोबां आन्थायाव सुजियो, गंसे बुथुम अबला मेसिन सुजि नङाबो।",
  "craft.stone.funFact": "आग्रानि फर बिजाबनाय शिल्पीफोरा दानसुबुं ताजमहलखौ सजायनाय बेनि रोखोमखौ दं मोनथिबाय।",
  "craft.bamboo.funFact": "गंसे बांथि बुथुम ३-५ बोसोरनि सिमायाव शिल्प थाखाय थायख बाहागो, बे गोरलौ बांथि गुदि निख्रुइ गोबां जोबोद।",
  "tips.modal.title": "दिनै नि रायजोमोन",
  "tips.modal.gotIt": "मोनदों",
  "tips.priceFloor": "गासैबो समनाव नोंथांनि गोसो सिमानि गुबुन दाम राखो — रं, नोंथांनि समय आरो प्लेटफर्म फी — गोरलौ दान आव आबो।",
  "tips.trackIncome": "गासैबो फेसानाय लिरगोन, गोदान जायबाबो। गंसे सोरबो आयनि लिरखा नोंथांखौ गोरलौ रादाब थाखाय आरो ऋणनि थाखाय आय दैथायगोन थाखाय हेल्पेर।",
  "tips.bulkOrders": "गोबां आरो संस्था फोरनि आदेश गोबसे आरो सिगांबो फोथाराव जागोन। नोंथांनि जोबथानाय आरो सजायथानाय समखौ गोदान राखो।",
  "tips.photoQuality": "गोसाय, गोबां जां आव आरो गोबां रोखोमनि फोटो जाय रादाब गोसो सोलैगोन। फुदुसिनि जां फ्लेशनिख्रुइ गोबां गाहाय।",
  "tips.respondFast": "नोंथाङ गंसे सान सिमाआव सोंलिगखौ जाबाब होगोन नोगोर खरेदार फोरा आदेश दैथायगोन गोबां सोदोब थायो।",
  "tips.saveSavings": "गासैबो फोथाराव निफ्राय गोदान भाग खोमोरखौ रोखा राखो — ५% बोबो गोदानसिन बाहायो।",
  "tips.giPremium": "GI टेग मूल जायगानि गोदान जायो, खरेदार फोरा जाबाब लायो। प्रमाणित रादाब फोरनि दाम गोबां दाबथाय जागोन दं — नोंथांनि रादाबखौ गोदान दाम मा।",
  "tips.restockEarly": "रं गोबसे जाबाय सिगां आबो सिगांबाय आदेश आरम्भ खालाम, बिसे पर्व आरो हादों समयनि सिगांआव।",
  "tips.clusterSupport": "नोंथांनि क्लस्टर संयोजक गोबां रं खरेदि आरो सिखा नाव हेल्पेर होगोन दं — गोमोर गुरु जानाय सिगां सोंलिग खालाम।",
  "tips.storySells": "खान्था जाय रादाब थाखाय खरेदार फोरा गोबां होयो। नोंथांनि प्रविधि अबला शिल्पनि इतिहासनि सायाव गंसे गोदान टोका जायो।",
